=== FILE: axil_timer.v ===
`timescale 1ns / 1ps
// axil_timer: 32-bit down-counting timer, one-shot and periodic modes,
// level interrupt, AXI4-Lite subordinate port.
// Requirement: req-2b2b91a584. Implements interface_spec.md per
// microarchitecture.md (channel logic of the axi4_lite register block).
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // ---------------------------------------------------------------
  // State
  // ---------------------------------------------------------------
  reg                  aw_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [31:0]           rdata_q;

  reg                  en;
  reg                  ie;
  reg                  mode;
  reg                  expired;
  reg [31:0]           load_q;
  reg [31:0]           count_q;

  // ---------------------------------------------------------------
  // Write channel (microarchitecture section 1)
  // ---------------------------------------------------------------
  wire awready    = !aw_held && !bvalid_q;
  wire wready     = !w_held && !bvalid_q;
  wire aw_hs      = s_axil_awvalid && awready;
  wire w_hs       = s_axil_wvalid && wready;
  wire aw_present = aw_held || aw_hs;
  wire w_present  = w_held || w_hs;
  wire do_write   = aw_present && w_present;

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held ? w_data_q : s_axil_wdata;
  wire [3:0]            wr_strb = w_held ? w_strb_q : s_axil_wstrb;

  // Read channel
  wire arready = !rvalid_q;
  wire ar_hs   = s_axil_arvalid && arready;

  // ---------------------------------------------------------------
  // Address decode (microarchitecture section 3)
  // ---------------------------------------------------------------
  wire wr_hi_zero;
  wire rd_hi_zero;
  generate
    if (ADDR_WIDTH > 4) begin : g_wide
      assign wr_hi_zero = (wr_addr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
      assign rd_hi_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    end else begin : g_narrow
      assign wr_hi_zero = 1'b1;
      assign rd_hi_zero = 1'b1;
    end
  endgenerate

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;
  wire [1:0] wr_idx    = wr_addr[3:2];
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  wire wr_ctrl   = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
  wire wr_load   = do_write && wr_mapped && (wr_idx == IDX_LOAD);
  wire wr_status = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                   wr_strb[0] && wr_data[0];
  wire wr_okay   = wr_mapped && (wr_idx != IDX_COUNT);

  // Last cycle of a count: COUNT at 1 or 0 while enabled.
  wire count_end = en && (count_q[31:1] == 31'd0);

  // Read mux
  reg [31:0] rd_value;
  always @* begin
    rd_value = 32'd0;
    if (rd_mapped) begin
      case (rd_idx)
        IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
        IDX_LOAD:   rd_value = load_q;
        IDX_COUNT:  rd_value = count_q;
        IDX_STATUS: rd_value = {31'd0, expired};
        default:    rd_value = 32'd0;
      endcase
    end
  end

  // ---------------------------------------------------------------
  // Write channel registers
  // ---------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held   <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_held    <= 1'b0;
      w_data_q  <= 32'd0;
      w_strb_q  <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
    end else begin
      if (bvalid_q && s_axil_bready) begin
        bvalid_q <= 1'b0;
      end
      if (do_write) begin
        aw_held  <= 1'b0;
        w_held   <= 1'b0;
        bvalid_q <= 1'b1;
        bresp_q  <= wr_okay ? RESP_OKAY : RESP_SLVERR;
      end else begin
        if (aw_hs) begin
          aw_held   <= 1'b1;
          aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
          w_held   <= 1'b1;
          w_data_q <= s_axil_wdata;
          w_strb_q <= s_axil_wstrb;
        end
      end
    end
  end

  // ---------------------------------------------------------------
  // Read channel registers
  // ---------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      rvalid_q <= 1'b0;
      rresp_q  <= RESP_OKAY;
      rdata_q  <= 32'd0;
    end else if (ar_hs) begin
      rvalid_q <= 1'b1;
      rdata_q  <= rd_value;
      rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
    end else if (rvalid_q && s_axil_rready) begin
      rvalid_q <= 1'b0;
    end
  end

  // ---------------------------------------------------------------
  // Timer (microarchitecture section 2; order gives the priorities)
  // ---------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      en      <= 1'b0;
      ie      <= 1'b0;
      mode    <= 1'b0;
      expired <= 1'b0;
      load_q  <= 32'd0;
      count_q <= 32'd0;
    end else begin
      // 1. Count step.
      if (en) begin
        if (count_end) begin
          if (mode) begin
            count_q <= load_q;
          end else begin
            count_q <= 32'd0;
            en      <= 1'b0;
          end
        end else begin
          count_q <= count_q - 32'd1;
        end
      end
      // 2. EXPIRED: clear, then set (a count end beats a clear).
      if (wr_status) begin
        expired <= 1'b0;
      end
      if (count_end) begin
        expired <= 1'b1;
      end
      // 3. CTRL write (wins over the count step for en and count).
      if (wr_ctrl) begin
        ie   <= wr_data[1];
        mode <= wr_data[2];
        en   <= wr_data[0];
        if (wr_data[0]) begin
          count_q <= load_q;
        end
      end
      // 4. LOAD write, byte merge.
      if (wr_load) begin
        if (wr_strb[0]) load_q[7:0]   <= wr_data[7:0];
        if (wr_strb[1]) load_q[15:8]  <= wr_data[15:8];
        if (wr_strb[2]) load_q[23:16] <= wr_data[23:16];
        if (wr_strb[3]) load_q[31:24] <= wr_data[31:24];
      end
    end
  end

  // ---------------------------------------------------------------
  // Outputs
  // ---------------------------------------------------------------
  assign s_axil_awready = awready;
  assign s_axil_wready  = wready;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = arready;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rdata   = rdata_q;
  assign s_axil_rresp   = rresp_q;
  assign irq            = expired && ie;

`ifdef FORMAL
  // Design-intent assertions (not a full proof; no .sby submitted).
  reg f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume(!aresetn);
    if (bvalid_q) assert(!aw_held && !w_held);
    if (count_end) assert(en);
    assert(irq == (expired && ie));
  end

  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(bvalid_q && !s_axil_bready))
        assert(bvalid_q && (bresp_q == $past(bresp_q)));
      if ($past(rvalid_q && !s_axil_rready))
        assert(rvalid_q && (rdata_q == $past(rdata_q)) && (rresp_q == $past(rresp_q)));
    end
  end
`endif

endmodule
=== END FILE ===
=== FILE: axil_timer_tb.v ===
`timescale 1ns / 1ps
// Self-checking testbench for axil_timer (interface_spec.md section 8).
// The main instance runs at ADDR_WIDTH 8; an ADDR_WIDTH 4 instance runs in
// lockstep until the test of offsets from 0x10 up.

`define CHECK(cond, msg) \
  begin \
    if (cond) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error msg; \
    end \
  end

module axil_timer_tb;
  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  reg aclk;
  initial aclk = 1'b0;
  always #5 aclk = ~aclk;

  reg        aresetn;
  reg  [7:0] s_axil_awaddr;
  reg        s_axil_awvalid;
  reg [31:0] s_axil_wdata;
  reg  [3:0] s_axil_wstrb;
  reg        s_axil_wvalid;
  reg        s_axil_bready;
  reg  [7:0] s_axil_araddr;
  reg        s_axil_arvalid;
  reg        s_axil_rready;

  wire        awready, wready, bvalid, arready, rvalid, irq;
  wire [1:0]  bresp, rresp;
  wire [31:0] rdata;

  wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
  wire [1:0]  bresp4, rresp4;
  wire [31:0] rdata4;

  axil_timer #(.ADDR_WIDTH(8)) dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(s_axil_awaddr), .s_axil_awvalid(s_axil_awvalid), .s_axil_awready(awready),
    .s_axil_wdata(s_axil_wdata), .s_axil_wstrb(s_axil_wstrb), .s_axil_wvalid(s_axil_wvalid),
    .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(s_axil_bready),
    .s_axil_araddr(s_axil_araddr), .s_axil_arvalid(s_axil_arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(s_axil_rready),
    .irq(irq)
  );

  axil_timer #(.ADDR_WIDTH(4)) dut4 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(s_axil_awaddr[3:0]), .s_axil_awvalid(s_axil_awvalid), .s_axil_awready(awready4),
    .s_axil_wdata(s_axil_wdata), .s_axil_wstrb(s_axil_wstrb), .s_axil_wvalid(s_axil_wvalid),
    .s_axil_wready(wready4),
    .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(s_axil_bready),
    .s_axil_araddr(s_axil_araddr[3:0]), .s_axil_arvalid(s_axil_arvalid), .s_axil_arready(arready4),
    .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(s_axil_rready),
    .irq(irq4)
  );

  // Edge counter: after rising edge k, cyc == k.
  integer cyc;
  initial cyc = 0;
  always @(posedge aclk) cyc <= cyc + 1;

  // Monitor, 1 time unit after each rising edge.
  integer wr_edge;
  integer irq_edge;
  integer irq_rises;
  integer lock_mismatch;
  reg     bvalid_d;
  reg     irq_d;
  initial begin
    wr_edge = -1;
    irq_edge = -1;
    irq_rises = 0;
    lock_mismatch = 0;
    bvalid_d = 1'b0;
    irq_d = 1'b0;
  end

  reg lock_en;

  always @(posedge aclk) begin
    #1;
    if (bvalid && !bvalid_d) wr_edge = cyc;
    if (irq && !irq_d) begin
      irq_edge = cyc;
      irq_rises = irq_rises + 1;
    end
    bvalid_d = bvalid;
    irq_d = irq;
    if (lock_en) begin
      if ((awready !== awready4) || (wready !== wready4) || (bvalid !== bvalid4) ||
          (bresp !== bresp4) || (arready !== arready4) || (rvalid !== rvalid4) ||
          (rresp !== rresp4) || (rdata !== rdata4) || (irq !== irq4)) begin
        lock_mismatch = lock_mismatch + 1;
        if (lock_mismatch <= 5)
          $error("ADDR_WIDTH 4 instance differs from ADDR_WIDTH 8 instance after edge %0d", cyc);
      end
    end
  end

  integer passed;
  integer failed;
  reg [8*64-1:0] nonce;

  // ---------------------------------------------------------------
  // Bus tasks (called at a falling edge; return at a falling edge)
  // ---------------------------------------------------------------
  task idle;
    input integer n;
    begin
      repeat (n) @(negedge aclk);
    end
  endtask

  // order: 0 AW and W together, 1 AW first, 2 W first
  task axi_write;
    input  [7:0]  addr;
    input  [31:0] data;
    input  [3:0]  strb;
    input  integer order;
    input  integer bdelay;
    output [1:0]  resp;
    reg aw_done, w_done, awh, wh;
    integer guard;
    begin
      aw_done = 1'b0;
      w_done = 1'b0;
      if (order != 2) begin
        s_axil_awaddr = addr;
        s_axil_awvalid = 1'b1;
      end
      if (order != 1) begin
        s_axil_wdata = data;
        s_axil_wstrb = strb;
        s_axil_wvalid = 1'b1;
      end
      while (!(aw_done && w_done)) begin
        awh = s_axil_awvalid && awready;
        wh = s_axil_wvalid && wready;
        @(negedge aclk);
        if (awh) begin
          aw_done = 1'b1;
          s_axil_awvalid = 1'b0;
          if (!w_done && order == 1) begin
            repeat (2) begin
              `CHECK(!bvalid && !awready, ("write %h: BVALID or AWREADY high with only the address held", addr))
              @(negedge aclk);
            end
            s_axil_wdata = data;
            s_axil_wstrb = strb;
            s_axil_wvalid = 1'b1;
          end
        end
        if (wh) begin
          w_done = 1'b1;
          s_axil_wvalid = 1'b0;
          if (!aw_done && order == 2) begin
            repeat (2) begin
              `CHECK(!bvalid && !wready, ("write %h: BVALID or WREADY high with only the data held", addr))
              @(negedge aclk);
            end
            s_axil_awaddr = addr;
            s_axil_awvalid = 1'b1;
          end
        end
      end
      guard = 0;
      while (!bvalid && guard < 20) begin
        @(negedge aclk);
        guard = guard + 1;
      end
      `CHECK(bvalid, ("write %h: no BVALID", addr))
      resp = bresp;
      repeat (bdelay) begin
        `CHECK(bvalid && (bresp == resp) && !awready && !wready, ("write %h: B channel or READY wrong under back-pressure", addr))
        @(negedge aclk);
      end
      s_axil_bready = 1'b1;
      @(negedge aclk);
      s_axil_bready = 1'b0;
      `CHECK(!bvalid, ("write %h: BVALID still high after the handshake", addr))
    end
  endtask

  task axi_read;
    input  [7:0]  addr;
    input  integer rdelay;
    output [31:0] data;
    output [1:0]  resp;
    reg ar_done, arh;
    integer guard;
    begin
      s_axil_araddr = addr;
      s_axil_arvalid = 1'b1;
      ar_done = 1'b0;
      while (!ar_done) begin
        arh = s_axil_arvalid && arready;
        @(negedge aclk);
        if (arh) begin
          ar_done = 1'b1;
          s_axil_arvalid = 1'b0;
        end
      end
      guard = 0;
      while (!rvalid && guard < 20) begin
        @(negedge aclk);
        guard = guard + 1;
      end
      `CHECK(rvalid, ("read %h: no RVALID", addr))
      data = rdata;
      resp = rresp;
      repeat (rdelay) begin
        `CHECK(rvalid && (rdata == data) && (rresp == resp) && !arready, ("read %h: R channel or ARREADY wrong under back-pressure", addr))
        @(negedge aclk);
      end
      s_axil_rready = 1'b1;
      @(negedge aclk);
      s_axil_rready = 1'b0;
      `CHECK(!rvalid, ("read %h: RVALID still high after the handshake", addr))
    end
  endtask

  task wr_ok;
    input [7:0]  addr;
    input [31:0] data;
    reg [1:0] r;
    begin
      axi_write(addr, data, 4'hF, 0, 0, r);
      `CHECK(r == RESP_OKAY, ("write %h: BRESP %b, wanted OKAY", addr, r))
    end
  endtask

  task wr_resp;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    input [1:0]  expr;
    reg [1:0] r;
    begin
      axi_write(addr, data, strb, 0, 0, r);
      `CHECK(r == expr, ("write %h: BRESP %b, wanted %b", addr, r, expr))
    end
  endtask

  task rd_check;
    input [7:0]  addr;
    input [31:0] expd;
    input [1:0]  expr;
    reg [31:0] d;
    reg [1:0]  r;
    begin
      axi_read(addr, 0, d, r);
      `CHECK((d == expd) && (r == expr), ("read %h: got %h/%b, wanted %h/%b", addr, d, r, expd, expr))
    end
  endtask

  task wait_irq;
    input integer base_n;
    input integer maxc;
    integer g;
    begin
      g = 0;
      while (irq_rises <= base_n && g < maxc) begin
        @(negedge aclk);
        g = g + 1;
      end
      `CHECK(irq_rises > base_n, ("no interrupt within %0d cycles", maxc))
    end
  endtask

  task oneshot_timed;
    input [31:0]  n_load;
    input integer len;
    integer b0, e0, b1;
    begin
      wr_ok(8'h04, n_load);
      b0 = irq_rises;
      wr_ok(8'h00, 32'h0000_0003);
      e0 = wr_edge;
      wait_irq(b0, len + 20);
      `CHECK(irq_edge - e0 == len, ("one-shot LOAD %0d: ended %0d edges after start, wanted %0d", n_load, irq_edge - e0, len))
      `CHECK(irq, ("one-shot LOAD %0d: irq not held high", n_load))
      rd_check(8'h00, 32'h0000_0002, RESP_OKAY);
      rd_check(8'h08, 32'h0000_0000, RESP_OKAY);
      rd_check(8'h0C, 32'h0000_0001, RESP_OKAY);
      wr_ok(8'h0C, 32'h0000_0001);
      `CHECK(!irq, ("one-shot LOAD %0d: irq high after STATUS clear", n_load))
      rd_check(8'h0C, 32'h0000_0000, RESP_OKAY);
      b1 = irq_rises;
      idle(len + 10);
      `CHECK((irq_rises == b1) && !irq, ("one-shot LOAD %0d: second interrupt", n_load))
    end
  endtask

  // ---------------------------------------------------------------
  // Watchdog
  // ---------------------------------------------------------------
  initial begin
    #2000000;
    $error("watchdog: simulation did not finish");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

  // ---------------------------------------------------------------
  // Main sequence
  // ---------------------------------------------------------------
  reg  [1:0]  t_resp;
  reg  [1:0]  t_resp2;
  reg  [31:0] t_data;
  reg  [31:0] expv;
  integer base, start_edge, target, stop_edge, s1, s2, clr, k;

  initial begin
    passed = 0;
    failed = 0;
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {(8*64){1'b0}};
    lock_en = 1'b1;
    aresetn = 1'b0;
    s_axil_awaddr = 8'h00;
    s_axil_awvalid = 1'b0;
    s_axil_wdata = 32'h0;
    s_axil_wstrb = 4'h0;
    s_axil_wvalid = 1'b0;
    s_axil_bready = 1'b0;
    s_axil_araddr = 8'h00;
    s_axil_arvalid = 1'b0;
    s_axil_rready = 1'b0;
    repeat (3) @(negedge aclk);
    `CHECK(!bvalid && !rvalid && !irq, ("BVALID, RVALID or irq high in reset"))
    aresetn = 1'b1;
    @(negedge aclk);

    // 1. Reset values.
    `CHECK(awready && wready && arready && !bvalid && !rvalid && !irq, ("READY/VALID wrong after reset"))
    rd_check(8'h00, 32'h0, RESP_OKAY);
    rd_check(8'h04, 32'h0, RESP_OKAY);
    rd_check(8'h08, 32'h0, RESP_OKAY);
    rd_check(8'h0C, 32'h0, RESP_OKAY);

    // 2. LOAD with partial strobes.
    axi_write(8'h04, 32'hFFFF_FFFF, 4'hF, 0, 0, t_resp);
    `CHECK(t_resp == RESP_OKAY, ("LOAD full write: BRESP %b", t_resp))
    rd_check(8'h04, 32'hFFFF_FFFF, RESP_OKAY);
    axi_write(8'h04, 32'h1234_5678, 4'b0101, 0, 0, t_resp);
    `CHECK(t_resp == RESP_OKAY, ("LOAD strobe 0101: BRESP %b", t_resp))
    rd_check(8'h04, 32'hFF34_FF78, RESP_OKAY);
    axi_write(8'h04, 32'hAABB_CCDD, 4'b0000, 0, 0, t_resp);
    `CHECK(t_resp == RESP_OKAY, ("LOAD empty strobe: BRESP %b", t_resp))
    rd_check(8'h04, 32'hFF34_FF78, RESP_OKAY);
    axi_write(8'h04, 32'h1122_3344, 4'b1010, 0, 0, t_resp);
    `CHECK(t_resp == RESP_OKAY, ("LOAD strobe 1010: BRESP %b", t_resp))
    rd_check(8'h04, 32'h1134_3378, RESP_OKAY);

    // 3. Channel orders and response back-pressure.
    axi_write(8'h04, 32'h0000_00A5, 4'hF, 1, 3, t_resp);
    `CHECK(t_resp == RESP_OKAY, ("AW-first write: BRESP %b", t_resp))
    axi_read(8'h04, 4, t_data, t_resp);
    `CHECK((t_data == 32'h0000_00A5) && (t_resp == RESP_OKAY), ("read after AW-first write: %h/%b", t_data, t_resp))
    axi_write(8'h04, 32'h0000_005A, 4'hF, 2, 5, t_resp);
    `CHECK(t_resp == RESP_OKAY, ("W-first write: BRESP %b", t_resp))
    rd_check(8'h04, 32'h0000_005A, RESP_OKAY);

    // 4. A read and a write accepted on the same edge.
    fork
      axi_write(8'h04, 32'h0000_00C3, 4'hF, 0, 0, t_resp);
      axi_read(8'h04, 0, t_data, t_resp2);
    join
    `CHECK(t_resp == RESP_OKAY, ("concurrent write: BRESP %b", t_resp))
    `CHECK((t_data == 32'h0000_005A) && (t_resp2 == RESP_OKAY), ("concurrent read: got %h/%b, wanted old value 5a", t_data, t_resp2))
    rd_check(8'h04, 32'h0000_00C3, RESP_OKAY);

    // 5. COUNT read only, unaligned addresses.
    wr_resp(8'h08, 32'h0000_1234, 4'hF, RESP_SLVERR);
    rd_check(8'h08, 32'h0, RESP_OKAY);
    wr_resp(8'h05, 32'hFFFF_FFFF, 4'hF, RESP_SLVERR);
    wr_resp(8'h06, 32'hFFFF_FFFF, 4'hF, RESP_SLVERR);
    wr_resp(8'h0D, 32'h0000_0001, 4'hF, RESP_SLVERR);
    rd_check(8'h04, 32'h0000_00C3, RESP_OKAY);
    rd_check(8'h06, 32'h0, RESP_SLVERR);
    rd_check(8'h01, 32'h0, RESP_SLVERR);
    rd_check(8'h0F, 32'h0, RESP_SLVERR);

    // 6. CTRL write without wstrb[0].
    wr_resp(8'h00, 32'h0000_0007, 4'b1110, RESP_OKAY);
    rd_check(8'h00, 32'h0, RESP_OKAY);
    idle(5);
    rd_check(8'h08, 32'h0, RESP_OKAY);

    // 7. One-shot counts timed to the edge.
    oneshot_timed(32'd5, 5);
    oneshot_timed(32'd1, 1);
    oneshot_timed(32'd0, 1);

    // 8. Interrupt enable on a pending expiry; STATUS write policy.
    wr_ok(8'h04, 32'd3);
    wr_ok(8'h00, 32'h0000_0001);
    idle(10);
    `CHECK(!irq, ("irq high with IE 0"))
    rd_check(8'h0C, 32'h1, RESP_OKAY);
    rd_check(8'h00, 32'h0, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0000);
    rd_check(8'h0C, 32'h1, RESP_OKAY);
    wr_resp(8'h0C, 32'h0000_0001, 4'b1110, RESP_OKAY);
    rd_check(8'h0C, 32'h1, RESP_OKAY);
    base = irq_rises;
    wr_ok(8'h00, 32'h0000_0002);
    `CHECK((irq_rises == base + 1) && (irq_edge == wr_edge) && irq, ("irq did not rise on the IE write edge %0d (rose %0d)", wr_edge, irq_edge))
    wr_ok(8'h00, 32'h0000_0000);
    `CHECK(!irq, ("irq high after IE written 0"))
    rd_check(8'h0C, 32'h1, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0001);
    rd_check(8'h0C, 32'h0, RESP_OKAY);

    // 9. Periodic counts over several periods.
    wr_ok(8'h04, 32'd10);
    base = irq_rises;
    wr_ok(8'h00, 32'h0000_0007);
    start_edge = wr_edge;
    for (k = 1; k <= 4; k = k + 1) begin
      wait_irq(base, 40);
      base = irq_rises;
      `CHECK(irq_edge == start_edge + 10 * k, ("periodic: expiry %0d on edge %0d, wanted %0d", k, irq_edge, start_edge + 10 * k))
      if (k == 2) begin
        rd_check(8'h00, 32'h0000_0007, RESP_OKAY);
      end
      wr_ok(8'h0C, 32'h0000_0001);
      `CHECK(!irq, ("periodic: irq high after clear %0d", k))
    end
    // A clear landing on the count-end edge loses to the new expiry.
    target = start_edge + 50;
    `CHECK(cyc < target - 1, ("testbench: too late to schedule the coincident clear"))
    while (cyc < target - 1) @(negedge aclk);
    axi_write(8'h0C, 32'h0000_0001, 4'hF, 0, 0, t_resp);
    `CHECK(wr_edge == target, ("coincident clear landed on edge %0d, wanted %0d", wr_edge, target))
    `CHECK(irq && (irq_edge == target), ("coincident clear: expiry lost (irq %b, rose %0d)", irq, irq_edge))
    rd_check(8'h0C, 32'h1, RESP_OKAY);

    // 10. Stop freezes COUNT.
    idle(3);
    wr_ok(8'h00, 32'h0000_0006);
    stop_edge = wr_edge;
    expv = 10 - ((stop_edge - start_edge) % 10);
    rd_check(8'h08, expv, RESP_OKAY);
    wr_resp(8'h08, 32'h0000_FFFF, 4'hF, RESP_SLVERR);
    idle(15);
    rd_check(8'h08, expv, RESP_OKAY);
    rd_check(8'h00, 32'h0000_0006, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0001);
    `CHECK(!irq, ("irq high after clear following stop"))
    base = irq_rises;
    idle(25);
    `CHECK((irq_rises == base) && !irq, ("expiry after stop"))

    // 11. Restart mid-count.
    wr_ok(8'h04, 32'd8);
    base = irq_rises;
    wr_ok(8'h00, 32'h0000_0003);
    s1 = wr_edge;
    idle(2);
    wr_ok(8'h00, 32'h0000_0003);
    s2 = wr_edge;
    `CHECK(s2 < s1 + 8, ("testbench: restart too late"))
    wait_irq(base, 30);
    `CHECK((irq_edge == s2 + 8) && (irq_rises == base + 1), ("restart: expiry on edge %0d, wanted %0d", irq_edge, s2 + 8))
    rd_check(8'h00, 32'h0000_0002, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0001);

    // 12. Restart landing on the count-end edge.
    base = irq_rises;
    wr_ok(8'h00, 32'h0000_0003);
    s1 = wr_edge;
    target = s1 + 8;
    while (cyc < target - 1) @(negedge aclk);
    axi_write(8'h00, 32'h0000_0003, 4'hF, 0, 0, t_resp);
    `CHECK(wr_edge == target, ("end-edge restart landed on edge %0d, wanted %0d", wr_edge, target))
    `CHECK((irq_rises == base + 1) && (irq_edge == target), ("end-edge restart: expiry not set on edge %0d", target))
    rd_check(8'h00, 32'h0000_0003, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0001);
    clr = wr_edge;
    `CHECK(clr < target + 8, ("testbench: clear after end-edge restart too late"))
    wait_irq(base + 1, 20);
    `CHECK(irq_edge == target + 8, ("end-edge restart: next expiry on edge %0d, wanted %0d", irq_edge, target + 8))
    rd_check(8'h00, 32'h0000_0002, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0001);

    // 13. Reset during a count.
    wr_ok(8'h04, 32'd20);
    wr_ok(8'h00, 32'h0000_0003);
    idle(5);
    aresetn = 1'b0;
    idle(2);
    `CHECK(!irq && !bvalid && !rvalid, ("outputs high during reset"))
    aresetn = 1'b1;
    @(negedge aclk);
    rd_check(8'h00, 32'h0, RESP_OKAY);
    rd_check(8'h04, 32'h0, RESP_OKAY);
    rd_check(8'h08, 32'h0, RESP_OKAY);
    rd_check(8'h0C, 32'h0, RESP_OKAY);
    base = irq_rises;
    idle(30);
    `CHECK((irq_rises == base) && !irq, ("expiry after reset during a count"))

    // 14. Offsets from 0x10 up at ADDR_WIDTH 8 (the 4-bit instance aliases them).
    `CHECK(lock_mismatch == 0, ("ADDR_WIDTH 4 instance diverged on %0d edges", lock_mismatch))
    lock_en = 1'b0;
    wr_ok(8'h04, 32'd2);
    wr_ok(8'h00, 32'h0000_0001);
    idle(6);
    rd_check(8'h0C, 32'h1, RESP_OKAY);
    wr_resp(8'h1C, 32'h0000_0001, 4'hF, RESP_SLVERR);
    rd_check(8'h0C, 32'h1, RESP_OKAY);
    wr_ok(8'h0C, 32'h0000_0001);
    wr_ok(8'h04, 32'h0000_0055);
    wr_resp(8'h14, 32'hFFFF_FFFF, 4'hF, RESP_SLVERR);
    rd_check(8'h04, 32'h0000_0055, RESP_OKAY);
    wr_resp(8'h10, 32'h0000_0003, 4'hF, RESP_SLVERR);
    rd_check(8'h00, 32'h0, RESP_OKAY);
    rd_check(8'h08, 32'h0, RESP_OKAY);
    wr_resp(8'h18, 32'h0000_0001, 4'hF, RESP_SLVERR);
    wr_resp(8'hF4, 32'h0000_00AA, 4'hF, RESP_SLVERR);
    rd_check(8'h04, 32'h0000_0055, RESP_OKAY);
    rd_check(8'h10, 32'h0, RESP_SLVERR);
    rd_check(8'h14, 32'h0, RESP_SLVERR);
    rd_check(8'h18, 32'h0, RESP_SLVERR);
    rd_check(8'h1C, 32'h0, RESP_SLVERR);
    rd_check(8'h84, 32'h0, RESP_SLVERR);
    rd_check(8'hFC, 32'h0, RESP_SLVERR);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

